 2 | import { AES, enc } from 'crypto-js'
 3 | import { getEncryptionKey } from '../../utils'
 4 | 
 5 | export function getPasswordSaltRounds(): number {
 6 |     return parseInt(process.env.PASSWORD_SALT_HASH_ROUNDS || '10', 10)
 7 | }
