 9 | /**
10 |  * Extracts the cost factor (salt rounds) from a bcrypt hash using bcrypt.getRounds().
11 |  * @returns The number of rounds used, or null if the string is not a valid bcrypt hash.
12 |  */
13 | export function getBcryptRoundsFromHash(hash: string): number | null {
14 |     try {
15 |         return bcrypt.getRounds(hash)
16 |     } catch {
17 |         return null
18 |     }
19 | }
20 | 
21 | /**
22 |  * Checks if a stored bcrypt hash was created with fewer rounds than the current minimum,
23 |  * and should be rehashed for stronger security.
24 |  * @param storedHash The bcrypt hash stored in the database.
25 |  * @param minRounds The minimum acceptable number of salt rounds (e.g. 10).
26 |  */
27 | export function hashNeedsUpgrade(storedHash: string, minRounds: number): boolean {
28 |     const rounds = getBcryptRoundsFromHash(storedHash)
29 |     return rounds !== null && rounds < minRounds
30 | }
